import 'package:flutter/material.dart';import 'package:go_router/go_router.dart';import 'package:sehatak/app_router.dart';import 'package:sehatak/core/models/pregnancy/pregnancy_models.dart';import 'package:sehatak/core/services/pregnancy_service.dart';class PregnancyClinicsScreen extends StatelessWidget{const PregnancyClinicsScreen({super.key});@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('عيادات متابعة الحمل')),body:StreamBuilder<List<PregnancyClinic>>(stream:PregnancyService().streamClinics(limit:20),builder:(c,s){if(!s.hasData)return const Center(child:CircularProgressIndicator());return ListView(padding:const EdgeInsets.all(16),children:s.data!.map((d)=>Card(child:ListTile(onTap:()=>c.push(AppRouter.pregnancyClinicDetail.replaceFirst(':id',d.id)),leading:const Icon(Icons.local_hospital),title:Text(d.name),subtitle:Text('${d.type} • ${d.address}'),trailing:Text(d.isOpen?'مفتوح':'مغلق')))).toList());}));}}
